mapper.select:
SELECT t.TRADE_ID tradeId,/**交易编号**/ NVL(deal1.BOOKSET_ID,deal2.BOOKSET_ID) prodId,/**金融产品代码**/ bok.BOOKSET_NAME prodName,/**金融产品名称**/ zc.FINPROD_ID secId, /**资产代码**/ zc.FINPROD_ABBR secAbbr,/**资产名称**/ t.PS ps,/**交易类型**/ t.CCY ccy,/**币种**/ t.VDATE vdate,/**计息开始日**/ t.MDATE mdate,/**计息结束日**/ t.TRADE_DATE tradeDate,/**交易日**/ t.SETTLE_DATE settleDate, /**交割日**/ nvl(t.INT_AMT,0) actInt, /**实收利息**/ nvl(t.PRIN_AMT,0) actCapi, /**实收本金**/ t.TRADE_AMT settleAmt,/**结算金额**/ t.MY_ACCT_NO myAcctNo/**资金账户**/ FROM TRD_PRODUCT_DEAL t LEFT JOIN FIN_PRODUCT zc on zc.finprod_id = t.finprod_id LEFT JOIN STL_ORDERS stl ON stl.TRADE_ID = t.TRADE_ID AND stl.BUSI_TYPE = #{busiType} LEFT JOIN BOK_DEAL_ACCOUNTING deal1 on deal1.BUSI_NO = t.TRADE_ID LEFT JOIN BOK_DEAL_ACCOUNTING deal2 ON stl.ORDER_ID = deal2.BUSI_NO LEFT JOIN BOK_BOOKSET bok on (bok.BOOKSET_ID = deal1.BOOKSET_ID) OR (bok.BOOKSET_ID = deal2.BOOKSET_ID) where t.BUSI_TYPE = #{busiType} and t.FINPROD_TYPE = #{finprodType}
and t.PS in(#{PS_T29}, #{PS_T32})
and t.TRADE_ID like concat(concat('%',#{tradeId}),'%')
and NVL(deal1.BOOKSET_ID,deal2.BOOKSET_ID) IN
#{finprodId}
and zc.FINPROD_ID IN
#{asset}
and t.TRADE_DATE >= to_date(#{tradeDateBegin},'yyyy-mm-dd')
and t.TRADE_DATE <= to_date(#{tradeDateEnd},'yyyy-mm-dd')
AND t.PS IN
#{ps}
order by t.TRADE_ID desc
